package com.memorevamp.common.id

import com.fasterxml.uuid.Generators
import org.springframework.stereotype.Component
import java.util.UUID

/** Primary keys are UUIDv7 generated by the application (AGENTS.md §4, ADR-0008). Inject this; never call a UUID factory. */
fun interface IdGenerator {
    fun next(): UUID
}

/** Time-ordered UUIDv7, monotonic within a millisecond (FasterXML JUG `TimeBasedEpochGenerator`). */
@Component
class UuidV7Generator : IdGenerator {
    private val generator = Generators.timeBasedEpochGenerator()

    override fun next(): UUID = generator.generate()
}
